# ABOUTME: Semantic semiring for building values during parsing with evaluation contexts
# ABOUTME: Tracks contexts and enables semantic actions via EvalContext comonad

use 5.42.0;
use experimental qw(class builtin keyword_any keyword_all);
use utf8;
use Chalk::Base;
use Chalk::EvalContext;

class Chalk::Semiring::SemanticElement :isa(Chalk::Element) {
    field $value :param :reader;         # Computed semantic value
    field $context :param :reader;       # Evaluation context
    field $sppf_node :param = undef;     # Optional SPPF node

    method add( $other, $swap = undef ) {
        # For alternatives (choice), prefer non-zero value
        # If self has value 0 (is add_id), return other
        if ($value == 0) {
            return $other;
        }

        # Prefer elements with evaluated focus (defined) over unevaluated (undef)
        # This handles the case where we update the chart after evaluation
        my $self_focus = $self->context->focus;
        my $other_focus = $other->context->focus;

        if (!defined($self_focus) && defined($other_focus)) {
            return $other;
        }
        if (defined($self_focus) && !defined($other_focus)) {
            return $self;
        }

        # For semantic values, prefer the alternative that consumed more input
        # (this handles ambiguous parses - longer parse is more complete)
        # Use parse span (end_pos - start_pos) as primary ranking
        my $self_span = $self->context->end_pos - $self->context->start_pos;
        my $other_span = $other->context->end_pos - $other->context->start_pos;

        if ($other_span > $self_span) {
            return $other;  # Other consumed more input, prefer it
        }
        if ($self_span > $other_span) {
            return $self;  # Self consumed more input, prefer it
        }

        # If spans are equal, prefer the alternative with more children
        # (handles cases where both consumed same input but one has more structure)
        my $self_children = scalar(@{$self->context->children});
        my $other_children = scalar(@{$other->context->children});

        if ($other_children > $self_children) {
            return $other;
        }

        # Otherwise prefer self (first alternative)
        return $self;
    }

    method multiply( $other, $swap = undef ) {
        # For sequences, append other's context to self's children
        # This builds up the children list as we advance the dot through the rule
        my @new_children = (@{$self->context->children}, $other->context);

        my $combined_ctx = Chalk::EvalContext->new(
            focus => undef,  # Not yet evaluated
            children => \@new_children,
            start_pos => $self->context->start_pos,
            end_pos => $other->context->end_pos,
            env => $self->context->env,
            grammar => $self->context->grammar,
            rule => $self->context->rule,
            forest => $self->context->forest
        );

        return Chalk::Semiring::SemanticElement->new(
            value => 1,  # Success value
            context => $combined_ctx,
            sppf_node => $sppf_node
        );
    }

    method equals( $other, $swap = undef ) {
        return 0 unless ref($other) eq ref($self);
        # Use refaddr for reference equality to avoid recursion
        # For semantic semiring, we want elements to be considered non-equal
        # to add_id unless they are literally the same object
        return refaddr($self) == refaddr($other) ? 1 : 0;
    }

    method score() {
        # Semantic semiring doesn't use numeric scores
        return 1;
    }

    method to_string(@args) {
        # Return value (0 for add_id, 1 for others) for Parser's numeric comparisons
        return defined($value) ? "$value" : '1';
    }
}

class Chalk::Semiring::Semantic :isa(Chalk::Semiring) {
    field $env :param = {};
    field $grammar :param :reader;
    field $shared_context :param :reader = undef;
    field $forest :reader;
    field $mul_id :reader;
    field $add_id :reader;
    field $_add_id_is_zero :reader = 1;  # Flag to identify add_id

    ADJUST {
        # Store reference to shared forest if provided
        $forest = defined($shared_context) && exists($shared_context->{forest})
            ? $shared_context->{forest}
            : undef;

        # Create identity elements with empty contexts
        my $empty_ctx_mul = Chalk::EvalContext->new(
            focus => undef,
            children => [],
            start_pos => 0,
            end_pos => 0,
            env => $env,
            grammar => $grammar,
            rule => undef,
            forest => $forest
        );

        my $empty_ctx_add = Chalk::EvalContext->new(
            focus => undef,
            children => [],
            start_pos => 0,
            end_pos => 0,
            env => $env,
            grammar => $grammar,
            rule => undef,
            forest => $forest
        );

        $mul_id = Chalk::Semiring::SemanticElement->new(
            value => 1,  # mul_id has value 1
            context => $empty_ctx_mul
        );

        $add_id = Chalk::Semiring::SemanticElement->new(
            value => 0,  # add_id has value 0 (failure/no parse)
            context => $empty_ctx_add
        );
    }

    method init_element_from_rule($rule, $start_pos = 0, $end_pos = 0, $parent_derivation_id = undef) {
        my $ctx = Chalk::EvalContext->new(
            focus => undef,
            children => [],
            start_pos => $start_pos,
            end_pos => $end_pos,
            env => $env,
            grammar => $grammar,
            rule => $rule,
            forest => $forest
        );

        return Chalk::Semiring::SemanticElement->new(
            value => 1,  # Success value (not add_id which is 0)
            context => $ctx
        );
    }

    method multiply($x, $y) {
        # For backward compatibility if called directly
        return $x->multiply($y);
    }

    method plus($x, $y) {
        # For backward compatibility if called directly
        return $x->add($y);
    }
}

content.content:
## Context

After proving IR generation works (issue #71), we should add type checking directly into the semantic actions. Rather than building untyped IR and then validating it in a separate pass, we generate typed IR from the start using Perl's latent type system - types inferred from sigils, operations, and context.

The latent type system is documented at: https://gist.github.com/perigrin/c4780a7511ba1421e49a4a8b385aaa3d

**Key Principle:** Types are implicit but checkable. No type annotations required.

**Architecture:** Types are inferred and checked during IR node creation:

```
Parse → SPPF → Semantic Actions (with type inference) → Typed IR
```

This is a refactoring of the semantic actions from issue #71 to add type information.

## Goals

1. Add type inference to semantic actions during IR generation
2. Semantic elements carry both IR nodes and type information
3. Validate type consistency during IR node composition
4. Fail fast with clear errors when types are incompatible
5. Enable type-directed IR optimizations

## Type System Specification

### Complete Type Lattice (Chalk Subset)

Based on the formal specification in https://gist.github.com/perigrin/c4780a7511ba1421e49a4a8b385aaa3d, restricted to Chalk's supported Perl subset:

```
                        Any (⊤)
                          |
        +-----------------+------------------+
        |                 |                  |
     Scalar             List              Code
        |                 |
        |                 +------+------+
        |                        |      |
        |                     Array   Hash
        |
        +--------+--------+--------+
        |        |        |        |
      Undef   Boolean    Str      Ref
                          |        |
                         Num       +----+----+----+
                          |        |    |    |    |
                         Int    Object ScalarRef ArrayRef
                                      HashRef CodeRef


                        None (⊥)
```

**Note:** Chalk does not support:
- Glob or GlobRef types (Perl symbol table entries)
- DualVar type (scalar dual-typed values)

### Key Subtyping Chains

**Primary Scalar Chain:**
```
Int <: Num <: Str <: Scalar <: Any
```

**Why Num <: Str?** Because numbers can round-trip through string conversion without loss:
- `42 → "42" → 42` (preserves value)
- But `"hello" → 0 → "0"` (loses information, so not all Str are Num)

**Other Chains:**
```
Undef <: Scalar <: Any
Boolean <: Scalar <: Any

Object <: Ref <: Scalar <: Any
ScalarRef <: Ref <: Scalar <: Any
ArrayRef <: Ref <: Scalar <: Any
HashRef <: Ref <: Scalar <: Any
CodeRef <: Ref <: Scalar <: Any

Array <: List <: Any
Hash <: List <: Any

Code <: Any

None <: (everything)
```

### Type Membership Definition

A value `v` belongs to type `T` if and only if **both** conditions hold:

1. **Syntactic Preservation**: Converting `v` to type `T` and back produces observationally equivalent results without information loss (round-trip coercion test)

2. **Semantic Fulfillment**: `v` satisfies all operational contracts defined for type `T`, ensuring meaningful behavior under `T`'s operations

**Example:** The string `"NaN"` passes syntactic preservation (round-trips through numeric interpretation) but fails semantic fulfillment because IEEE NaN violates reflexivity (`NaN ≠ NaN`). Therefore `"NaN" ∉ Num`.

### Critical Coercion Rules

**Numeric Coercion (⇓^Num):**
- Numeric literals remain themselves: `42 → 42`
- Valid numeric strings parse: `"42" → 42`, `"3.14" → 3.14`
- Invalid strings become 0: `"hello" → 0`
- References coerce to memory addresses: `\$x → 0x7f8a...`

**String Coercion (⇓^Str):**
- Strings remain unchanged: `"hello" → "hello"`
- Numbers stringify: `42 → "42"`, `3.14 → "3.14"`
- References show type+address: `\$x → "SCALAR(0x...)"`, `\@arr → "ARRAY(0x...)"`

**Boolean Coercion (⇓^Bool):**
- `true/false` preserve themselves (Perl 5.36+)
- `0`, `''`, `undef` are falsy
- All other values are truthy

### Special Type Semantics

