     1→# ABOUTME: Semantic semiring for building values during parsing with evaluation contexts
     2→# ABOUTME: Tracks contexts and enables semantic actions via EvalContext comonad
     3→
     4→use 5.42.0;
     5→use experimental qw(class builtin keyword_any keyword_all);
     6→use utf8;
     7→use Chalk::Base;
     8→use Chalk::EvalContext;
     9→
    10→class Chalk::Semiring::SemanticElement :isa(Chalk::Element) {
    11→    field $value :param :reader;         # Computed semantic value
    12→    field $context :param :reader;       # Evaluation context
    13→    field $sppf_node :param = undef;     # Optional SPPF node
    14→
    15→    method add( $other, $swap = undef ) {
    16→        # For alternatives (choice), prefer non-zero value
    17→        # If self has value 0 (is add_id), return other
    18→        if ($value == 0) {
    19→            return $other;
    20→        }
    21→
    22→        # Prefer elements with evaluated focus (defined) over unevaluated (undef)
    23→        # This handles the case where we update the chart after evaluation
    24→        my $self_focus = $self->context->focus;
    25→        my $other_focus = $other->context->focus;
    26→
    27→        if (!defined($self_focus) && defined($other_focus)) {
    28→            return $other;
    29→        }
    30→        if (defined($self_focus) && !defined($other_focus)) {
    31→            return $self;
    32→        }
    33→
    34→        # For semantic values, prefer the alternative that consumed more input
    35→        # (this handles ambiguous parses - longer parse is more complete)
    36→        # Use parse span (end_pos - start_pos) as primary ranking
    37→        my $self_span = $self->context->end_pos - $self->context->start_pos;
    38→        my $other_span = $other->context->end_pos - $other->context->start_pos;
    39→
    40→        if ($other_span > $self_span) {
    41→            return $other;  # Other consumed more input, prefer it
    42→        }
    43→        if ($self_span > $other_span) {
    44→            return $self;  # Self consumed more input, prefer it
    45→        }
    46→
    47→        # If spans are equal, prefer the alternative with more children
    48→        # (handles cases where both consumed same input but one has more structure)
    49→        my $self_children = scalar(@{$self->context->children});
    50→        my $other_children = scalar(@{$other->context->children});
    51→
    52→        if ($other_children > $self_children) {
    53→            return $other;
    54→        }
    55→
    56→        # Otherwise prefer self (first alternative)
    57→        return $self;
    58→    }
    59→
    60→    method multiply( $other, $swap = undef ) {
    61→        # For sequences, append other's context to self's children
    62→        # This builds up the children list as we advance the dot through the rule
    63→        my @new_children = (@{$self->context->children}, $other->context);
    64→
    65→        my $combined_ctx = Chalk::EvalContext->new(
    66→            focus => undef,  # Not yet evaluated
    67→            children => \@new_children,
    68→            start_pos => $self->context->start_pos,
    69→            end_pos => $other->context->end_pos,
    70→            env => $self->context->env,
    71→            grammar => $self->context->grammar,
    72→            rule => $self->context->rule,
    73→            forest => $self->context->forest
    74→        );
    75→
    76→        return Chalk::Semiring::SemanticElement->new(
    77→            value => 1,  # Success value
    78→            context => $combined_ctx,
    79→            sppf_node => $sppf_node
    80→        );
    81→    }
    82→
    83→    method equals( $other, $swap = undef ) {
    84→        return 0 unless ref($other) eq ref($self);
    85→        # Use refaddr for reference equality to avoid recursion
    86→        # For semantic semiring, we want elements to be considered non-equal
    87→        # to add_id unless they are literally the same object
    88→        return refaddr($self) == refaddr($other) ? 1 : 0;
    89→    }
    90→
    91→    method score() {
    92→        # Semantic semiring doesn't use numeric scores
    93→        return 1;
    94→    }
    95→
    96→    method to_string(@args) {
    97→        # Return value (0 for add_id, 1 for others) for Parser's numeric comparisons
    98→        return defined($value) ? "$value" : '1';
    99→    }
   100→}
   101→
   102→class Chalk::Semiring::Semantic :isa(Chalk::Semiring) {
   103→    field $env :param = {};
   104→    field $grammar :param :reader;
   105→    field $shared_context :param :reader = undef;
   106→    field $forest :reader;
   107→    field $mul_id :reader;
   108→    field $add_id :reader;
   109→    field $_add_id_is_zero :reader = 1;  # Flag to identify add_id
   110→
   111→    ADJUST {
   112→        # Store reference to shared forest if provided
   113→        $forest = defined($shared_context) && exists($shared_context->{forest})
   114→            ? $shared_context->{forest}
   115→            : undef;
   116→
   117→        # Create identity elements with empty contexts
   118→        my $empty_ctx_mul = Chalk::EvalContext->new(
   119→            focus => undef,
   120→            children => [],
   121→            start_pos => 0,
   122→            end_pos => 0,
   123→            env => $env,
   124→            grammar => $grammar,
   125→            rule => undef,
   126→            forest => $forest
   127→        );
   128→
   129→        my $empty_ctx_add = Chalk::EvalContext->new(
   130→            focus => undef,
   131→            children => [],
   132→            start_pos => 0,
   133→            end_pos => 0,
   134→            env => $env,
   135→            grammar => $grammar,
   136→            rule => undef,
   137→            forest => $forest
   138→        );
   139→
   140→        $mul_id = Chalk::Semiring::SemanticElement->new(
   141→            value => 1,  # mul_id has value 1
   142→            context => $empty_ctx_mul
   143→        );
   144→
   145→        $add_id = Chalk::Semiring::SemanticElement->new(
   146→            value => 0,  # add_id has value 0 (failure/no parse)
   147→            context => $empty_ctx_add
   148→        );
   149→    }
   150→
   151→    method init_element_from_rule($rule, $start_pos = 0, $end_pos = 0, $parent_derivation_id = undef) {
   152→        my $ctx = Chalk::EvalContext->new(
   153→            focus => undef,
   154→            children => [],
   155→            start_pos => $start_pos,
   156→            end_pos => $end_pos,
   157→            env => $env,
   158→            grammar => $grammar,
   159→            rule => $rule,
   160→            forest => $forest
   161→        );
   162→
   163→        return Chalk::Semiring::SemanticElement->new(
   164→            value => 1,  # Success value (not add_id which is 0)
   165→            context => $ctx
   166→        );
   167→    }
   168→
   169→    method multiply($x, $y) {
   170→        # For backward compatibility if called directly
   171→        return $x->multiply($y);
   172→    }
   173→
   174→    method plus($x, $y) {
   175→        # For backward compatibility if called directly
   176→        return $x->add($y);
   177→    }
   178→}
