            end_pos => 0,
            env => $env,
            grammar => $grammar,
            rule => undef,
            forest => $forest
        );

        $mul_id = Chalk::Semiring::SemanticElement->new(
            value => 1,  # mul_id has value 1
            context => $empty_ctx_mul
        );

        $add_id = Chalk::Semiring::SemanticElement->new(
