+    my $any = Chalk::Type::Any->new();
+    my $none = Chalk::Type::None->new();
--
+    isa_ok($none, 'Chalk::Type');
+    ok($none->is_bottom(), 'None is bottom type');
+    ok($none->is_subtype_of($any), 'None <: Any');
+};

