     1→# ABOUTME: Semantic semiring for building values during parsing with evaluation contexts
     2→# ABOUTME: Tracks contexts and enables semantic actions via EvalContext comonad
     3→
     4→use 5.42.0;
     5→use experimental qw(class builtin keyword_any keyword_all);
     6→use utf8;
     7→use Chalk::Base;
     8→use Chalk::EvalContext;
     9→use Chalk::Type::Int;
    10→use Chalk::Type::Num;
    11→use Chalk::Type::Str;
    12→use Chalk::Type::Scalar;
    13→use Chalk::Type::Array;
    14→use Chalk::Type::Hash;
    15→use Chalk::Type::List;
    16→use Chalk::Type::Any;
    17→
    18→class Chalk::Semiring::SemanticElement :isa(Chalk::Element) {
    19→    field $value :param :reader;         # Computed semantic value
    20→    field $context :param :reader;       # Evaluation context
    21→    field $sppf_node :param = undef;     # Optional SPPF node
    22→
    23→    method add( $other, $swap = undef ) {
    24→        # For alternatives (choice), prefer non-zero value
    25→        # If self has value 0 (is add_id), return other
    26→        if ($value == 0) {
    27→            return $other;
    28→        }
    29→
    30→        # Prefer elements with evaluated focus (defined) over unevaluated (undef)
    31→        # This handles the case where we update the chart after evaluation
    32→        my $self_focus = $self->context->focus;
    33→        my $other_focus = $other->context->focus;
    34→
    35→        if (!defined($self_focus) && defined($other_focus)) {
    36→            return $other;
    37→        }
    38→        if (defined($self_focus) && !defined($other_focus)) {
    39→            return $self;
    40→        }
    41→
    42→        # For semantic values, prefer the alternative that consumed more input
    43→        # (this handles ambiguous parses - longer parse is more complete)
    44→        # Use parse span (end_pos - start_pos) as primary ranking
    45→        my $self_span = $self->context->end_pos - $self->context->start_pos;
    46→        my $other_span = $other->context->end_pos - $other->context->start_pos;
    47→
    48→        if ($other_span > $self_span) {
    49→            return $other;  # Other consumed more input, prefer it
    50→        }
    51→        if ($self_span > $other_span) {
    52→            return $self;  # Self consumed more input, prefer it
    53→        }
    54→
    55→        # If spans are equal, prefer the alternative with more children
    56→        # (handles cases where both consumed same input but one has more structure)
    57→        my $self_children = scalar(@{$self->context->children});
    58→        my $other_children = scalar(@{$other->context->children});
    59→
    60→        if ($other_children > $self_children) {
    61→            return $other;
    62→        }
    63→
    64→        # Otherwise prefer self (first alternative)
    65→        return $self;
    66→    }
    67→
    68→    method multiply( $other, $swap = undef ) {
    69→        # For sequences, append other's context to self's children
    70→        # This builds up the children list as we advance the dot through the rule
    71→        my @new_children = (@{$self->context->children}, $other->context);
    72→
    73→        # Type propagation: keep the type from self's context (the rule being built)
    74→        my $combined_ctx = Chalk::EvalContext->new(
    75→            focus => undef,  # Not yet evaluated
    76→            children => \@new_children,
    77→            start_pos => $self->context->start_pos,
    78→            end_pos => $other->context->end_pos,
    79→            env => $self->context->env,
    80→            grammar => $self->context->grammar,
    81→            rule => $self->context->rule,
    82→            forest => $self->context->forest,
    83→            type => $self->context->type  # Propagate type from rule
    84→        );
    85→
    86→        return Chalk::Semiring::SemanticElement->new(
    87→            value => 1,  # Success value
    88→            context => $combined_ctx,
    89→            sppf_node => $sppf_node
    90→        );
    91→    }
    92→
    93→    method equals( $other, $swap = undef ) {
    94→        return 0 unless ref($other) eq ref($self);
    95→        # Use refaddr for reference equality to avoid recursion
    96→        # For semantic semiring, we want elements to be considered non-equal
    97→        # to add_id unless they are literally the same object
    98→        return refaddr($self) == refaddr($other) ? 1 : 0;
    99→    }
   100→
   101→    method score() {
   102→        # Semantic semiring doesn't use numeric scores
   103→        return 1;
   104→    }
   105→
   106→    method to_string(@args) {
   107→        # Return value (0 for add_id, 1 for others) for Parser's numeric comparisons
   108→        return defined($value) ? "$value" : '1';
   109→    }
   110→}
