        # Is this the top type (Any)?
        return 0;
    }

    method is_bottom() {
        # Is this the bottom type (None)?
        return 0;
    }

    method is_compatible_with($other) {
        # Two types are compatible if one is a subtype of the other
        return $self->is_subtype_of($other) || $other->is_subtype_of($self);
    }
}

