    80→class Chalk::Grammar::Chalk::Rule::Assignment :isa(Chalk::GrammarRule) {
    81→    method evaluate($context) {
    82→        # Assignment -> Ternary (pass-through)
    83→        # Assignment -> Ternary WS_OPT '=' WS_OPT Assignment
    84→        # Assignment -> Ternary WS_OPT %ASSIGN_OP% WS_OPT Assignment (TODO: compound assignment)
    85→
    86→        my @children = $context->children->@*;
    87→        my $builder = $context->env->{ir_builder};
    88→
    89→        # Check if this is an assignment operation (has '=' operator)
    90→        my $has_assignment = 0;
    91→        my $equals_index = -1;
    92→        for my $i (0..$#children) {
    93→            my $child = $children[$i]->extract;
    94→            if (defined($child) && !ref($child) && $child eq '=') {
    95→                $has_assignment = 1;
    96→                $equals_index = $i;
    97→                last;
    98→            }
    99→        }
   100→
   101→        # If no '=' operator, just pass through the Ternary child
   102→        return $context->child(0) unless $has_assignment;
   103→
   104→        # We have an assignment: Ternary = Assignment
   105→        return $context->child(0) unless $builder;
   106→
   107→        # Get left side (variable being assigned to)
   108→        my $lhs = $context->child(0);
   109→
   110→        # Extract variable name from lhs
   111→        # Three possible cases:
   112→        # 1. Variable metadata hash (from ScalarVar before Primary processes it)
   113→        # 2. Load node (from regular variables after Primary)
   114→        # 3. Proj node (from parameters - build_load_node returns Proj directly for params)
   115→        my $var_name;
   116→        if (ref($lhs) eq 'HASH' && $lhs->{type} eq 'scalar_var') {
   117→            # Case 1: Variable metadata
   118→            $var_name = $lhs->{name};
   119→        } elsif (blessed($lhs) && $lhs->can('op')) {
   120→            if ($lhs->op eq 'Load') {
   121→                # Case 2: Load node from regular variable
   122→                $var_name = $lhs->attributes->{name};
   123→            } elsif ($lhs->op eq 'Proj') {
   124→                # Case 3: Proj node from parameter
   125→                $var_name = $lhs->attributes->{label};
   126→            } else {
   127→                # Unsupported node type for assignment target
   128→                return $context->child(0);
   129→            }
   130→        } else {
   131→            # Can't handle this lhs type for assignment
   132→            return $context->child(0);
   133→        }
   134→
   135→        # Get right side (value to assign) - after '=' + WS_OPT, which is equals_index + 2
   136→        my $rhs_index = $equals_index + 2;
   137→
   138→        # Query parse alternatives for RHS to handle ambiguous parses
   139→        # For expressions like "$i = $i - 1", SPPF may create multiple parse trees
   140→        my @rhs_alternatives = $context->child_alternatives($rhs_index);
   141→
   142→        my $rhs;
   143→        if (@rhs_alternatives > 1) {
   144→            # Multiple parse alternatives exist - evaluate each and pick best
   145→            # The "best" is the one with most complete IR structure
   146→
   147→            my $candidate_values = [];
   148→            for my $alt_ctx (@rhs_alternatives) {
   149→                # Extract semantic value from this alternative's context
