     1→# ABOUTME: Implementation of type coercion rules (to Num, to Str, to Bool)
     2→# ABOUTME: Provides formal coercion functions per latent type spec (Issue #74 Phase 4)
     3→
     4→use 5.042;
     5→use experimental qw(class);
     6→
     7→class Chalk::Type::Coercion {
     8→    use Scalar::Util qw(looks_like_number refaddr);
     9→
    10→    # Numeric coercion: to_num
    11→    # Per spec: numbers stay, valid numeric strings parse, invalid to 0, refs to address
    12→    method to_num($value, $source_type) {
    13→        # Undef coerces to 0
    14→        if (ref($source_type) eq 'Chalk::Type::Undef') {
    15→            return 0;
    16→        }
    17→
    18→        return 0 unless defined $value;
    19→
    20→        # Numbers remain unchanged (Int <: Num via is_subtype_of, not Perl isa)
    21→        # Check by type name since our type hierarchy uses is_subtype_of not Perl inheritance
    22→        my $type_name = ref($source_type);
    23→        if ($type_name eq 'Chalk::Type::Int' ||
    24→            $type_name eq 'Chalk::Type::Num') {
    25→            return $value;
    26→        }
    27→
    28→        # Strings coerce to numbers (but not Num types, which we handled above)
    29→        if (ref($source_type) eq 'Chalk::Type::Str') {
    30→            # Valid numeric strings parse
    31→            if (looks_like_number($value)) {
    32→                return $value + 0;  # Force numeric context
    33→            }
    34→            # Invalid strings to 0
    35→            return 0;
    36→        }
    37→
    38→        # References coerce to memory addresses
    39→        # Check by type name prefix since our Ref types use is_subtype_of not Perl inheritance
    40→        if ($type_name =~ qr/^Chalk::Type::(?:Ref|.*Ref|Object)$/) {
    41→            return refaddr($value);
    42→        }
    43→
    44→        die "Cannot coerce " . $source_type->name() . " to Num";
    45→    }
    46→
    47→    # String coercion: to_str
    48→    # Per spec: strings stay, numbers stringify, refs show type+address, undef to empty
    49→    method to_str($value, $source_type) {
    50→        # Undef coerces to empty string
    51→        if (ref($source_type) eq 'Chalk::Type::Undef') {
    52→            return "";
    53→        }
    54→
    55→        return "" unless defined $value;
    56→
    57→        # Strings, Nums, and Ints all stringify
    58→        # Since Num <: Str in our lattice, all these can be stringified
    59→        my $type_name = ref($source_type);
    60→        if ($type_name eq 'Chalk::Type::Str' ||
    61→            $type_name eq 'Chalk::Type::Num' ||
    62→            $type_name eq 'Chalk::Type::Int') {
    63→            return "$value";  # Stringify to ensure string context
    64→        }
    65→
    66→        # References stringify to TYPE(0x...)
    67→        # Check by type name prefix since our Ref types use is_subtype_of not Perl inheritance
    68→        if ($type_name =~ qr/^Chalk::Type::(?:Ref|.*Ref|Object)$/) {
    69→            # Let Perl handle reference stringification
    70→            return "$value";
    71→        }
    72→
    73→        die "Cannot coerce " . $source_type->name() . " to Str";
    74→    }
