     1→#!/usr/bin/env perl
     2→# ABOUTME: CLI application for Chalk parser with grammar loading and input processing
     3→# ABOUTME: Supports grammar modules via -g option (e.g., -g Perl loads Chalk::Grammar::Perl)
     4→use 5.42.0;
     5→use experimental qw(class builtin keyword_any keyword_all);
     6→use utf8;
     7→use open qw(:std :utf8);
     8→use lib 'lib';
     9→use lib 'tools';
    10→
    11→use Chalk;
    12→
    13→# Main execution when run as script
    14→if ( !caller ) {
    15→    # Parse command line options
    16→    my $grammar_module = "Perl";  # default grammar module
    17→    my $semiring_type = "SPPF";   # default semiring
    18→    my $syntax_check_mode = 0;    # -c flag for syntax checking
    19→    my $compile_module_mode = 0;  # --compile-module flag
    20→    my $module_to_compile;        # module name for compilation
    21→    my $generate_ir_mode = 0;     # --generate-ir flag for batch IR generation
    22→    my $output_format = 'text';   # --output-format for IR output (text, json, dot)
    23→    my $preprocess = ['Chalk::Preprocessor::Heredoc'];  # default to Heredoc
    24→    my @remaining_args;
    25→
    26→    my $i = 0;
    27→    while ($i <= $#ARGV) {
    28→        if ($ARGV[$i] eq '-g' && $i < $#ARGV) {
    29→            $grammar_module = $ARGV[$i + 1];
    30→            $i += 2; # skip both -g and the grammar module name
    31→        } elsif ($ARGV[$i] eq '--semiring' && $i < $#ARGV) {
    32→            $semiring_type = $ARGV[$i + 1];
    33→            $i += 2; # skip both --semiring and the semiring type
    34→        } elsif ($ARGV[$i] eq '-c') {
    35→            $syntax_check_mode = 1;
    36→            $semiring_type = "Boolean";  # -c implies Boolean semiring
    37→            $i++;
    38→        } elsif ($ARGV[$i] eq '--compile-module' && $i < $#ARGV) {
    39→            $compile_module_mode = 1;
    40→            $module_to_compile = $ARGV[$i + 1];
