     1→# ABOUTME: Implementation of type coercion rules (to Num, to Str, to Bool)
     2→# ABOUTME: Provides formal coercion functions per latent type spec (Issue #74 Phase 4)
     3→
     4→use 5.042;
     5→use experimental qw(class);
     6→
     7→class Chalk::Type::Coercion {
     8→    use Scalar::Util qw(looks_like_number refaddr);
     9→    use Chalk::Type::Exception;
    10→    use Chalk::Type::Num;
    11→    use Chalk::Type::Str;
    12→
    13→    # Numeric coercion: to_num
    14→    # Per spec: numbers stay, valid numeric strings parse, invalid to 0, refs to address
    15→    method to_num($value, $source_type) {
    16→        # Undef coerces to 0
    17→        if (ref($source_type) eq 'Chalk::Type::Undef') {
    18→            return 0;
    19→        }
    20→
    21→        return 0 unless defined $value;
    22→
    23→        # Numbers remain unchanged (Int <: Num via is_subtype_of, not Perl isa)
    24→        # Check by type name since our type hierarchy uses is_subtype_of not Perl inheritance
    25→        my $type_name = ref($source_type);
    26→        if ($type_name eq 'Chalk::Type::Int' ||
    27→            $type_name eq 'Chalk::Type::Num') {
    28→            return $value;
    29→        }
    30→
    31→        # Strings coerce to numbers (but not Num types, which we handled above)
    32→        if (ref($source_type) eq 'Chalk::Type::Str') {
    33→            # Valid numeric strings parse
    34→            if (looks_like_number($value)) {
    35→                return $value + 0;  # Force numeric context
    36→            }
    37→            # Invalid strings to 0 (with warning about information loss)
    38→            warn "Warning: information loss in coercion from Str to Num (value: '$value') in context: non-numeric string coerced to 0";
    39→            return 0;
    40→        }
    41→
    42→        # References coerce to memory addresses
    43→        # Check by type name prefix since our Ref types use is_subtype_of not Perl inheritance
    44→        if ($type_name =~ qr/^Chalk::Type::(?:Ref|.*Ref|Object)$/) {
    45→            return refaddr($value);
    46→        }
    47→
    48→        Chalk::Type::Exception->new(
    49→            message => "Cannot coerce value from " . $source_type->name() .
    50→                       " to Num",
    51→            source_type => $source_type,
    52→            target_type => Chalk::Type::Num->new(),
    53→            value => $value,
    54→            context => "numeric coercion"
    55→        )->throw();
    56→    }
    57→
    58→    # String coercion: to_str
    59→    # Per spec: strings stay, numbers stringify, refs show type+address, undef to empty
    60→    method to_str($value, $source_type) {
    61→        # Undef coerces to empty string
    62→        if (ref($source_type) eq 'Chalk::Type::Undef') {
    63→            return "";
    64→        }
    65→
    66→        return "" unless defined $value;
    67→
    68→        # Strings, Nums, and Ints all stringify
    69→        # Since Num <: Str in our lattice, all these can be stringified
    70→        my $type_name = ref($source_type);
    71→        if ($type_name eq 'Chalk::Type::Str' ||
    72→            $type_name eq 'Chalk::Type::Num' ||
    73→            $type_name eq 'Chalk::Type::Int') {
    74→            return "$value";  # Stringify to ensure string context
    75→        }
    76→
    77→        # References stringify to TYPE(0x...)
    78→        # Check by type name prefix since our Ref types use is_subtype_of not Perl inheritance
    79→        if ($type_name =~ qr/^Chalk::Type::(?:Ref|.*Ref|Object)$/) {
    80→            # Let Perl handle reference stringification
    81→            return "$value";
    82→        }
    83→
    84→        Chalk::Type::Exception->new(
    85→            message => "Cannot coerce value from " . $source_type->name() .
    86→                       " to Str",
    87→            source_type => $source_type,
    88→            target_type => Chalk::Type::Str->new(),
    89→            value => $value,
    90→            context => "string coercion"
    91→        )->throw();
    92→    }
    93→
    94→    # Boolean coercion: to_bool
    95→    # Per spec: 0, empty string, undef are falsy; all else truthy
    96→    method to_bool($value, $source_type) {
    97→        # Undef is falsy
    98→        return 0 unless defined $value;
    99→
   100→        # Use Perl's native boolean context
   101→        # In Perl, these are falsy: undef, 0, '', "0"
   102→        # Everything else is truthy
